namespace {
int checks=0;void require(bool yes,const char* why){checks++;if(!yes)throw std::runtime_error(why);}
energy::Image blank(int w=256,int h=240){return {w,h,0,0,std::vector<float>(std::size_t(w)*h*4)};}
void coverage(energy::Image& image,int x,int y,double a){image.rgba[(std::size_t(y)*image.width+x)*4+3]=float(a);}
double alpha(const energy::Image& image,int x,int y){return image.rgba[(std::size_t(y)*image.width+x)*4+3];}
void ppm(const std::filesystem::path& file,const energy::Image& image){std::ofstream out(file,std::ios::binary);out<<"P6\n"<<image.width<<' '<<image.height<<"\n255\n";for(std::size_t i=0;i<image.rgba.size();i+=4)for(int k=0;k<3;k++){auto v=std::uint8_t(std::lround(std::clamp(image.rgba[i+k]*image.rgba[i+3],0.f,1.f)*255));out.write(reinterpret_cast<const char*>(&v),1);}}
}
