 Path contour;require(trace_alpha(src,50,contour)&&contour.curves.size()==2,"Alpha contour retains outer boundary and hole");for(const auto& c:contour.curves)require(c.closed&&c.knots.size()>=3&&c.knots.size()<=10,"closed rings simplified without bridging holes");
