 auto noisy=blank(160,160);for(int y=0;y<160;y+=2)for(int x=0;x<160;x+=2)coverage(noisy,x,y,1);a=unchanged;require(!trace_alpha(noisy,50,a)&&a==unchanged,"complexity limit rejects without truncating or changing the old contour");
 auto line=defaults(256,240);line.start_x=35;line.end_x=221;line.start_y=line.end_y=160;line.width=2;line.glow_radius=12;line.composite=1;auto electric=material_preset(1,line);electric.seed=123;Image e1,e2,e3;require(render(empty,electric,{},e1)&&render(empty,electric,{},e2)&&e1.rgba==e2.rgba,"electric seed is exactly repeatable");auto different=electric;different.seed++;require(render(empty,different,{},e3)&&e3.rgba!=e1.rgba,"electric seed changes geometry");different=electric;different.evolution=65;require(render(empty,different,{},e3)&&e3.rgba!=e1.rgba,"electric evolution changes shape");ppm(dir/"electric.ppm",e1);
 electric.glow_radius=0;electric.branches=0;require(render(empty,electric,{},e1),"electric without branches");require(alpha(e1,35,160)>.1&&alpha(e1,220,160)>.1,"open electric endpoints stay attached");auto branches=electric;branches.branches=12;branches.branch_length=80;require(render(empty,branches,{},e2),"branched electric");int extra=0;for(std::size_t i=3;i<e1.rgba.size();i+=4)if(e2.rgba[i]>e1.rgba[i]+.01)extra++;require(extra>50,"branches add visible off-core pixels");
